const CACHE_NAME='safekit-shell-v3';
const SHELL=['./','./index.html','./offline.html','./faq.html','./sources.html','./privacy.html','./terms.html','./affiliate.html','./manifest.webmanifest','./robots.txt','./sitemap.xml','./favicon.ico','./icon-192.png','./icon-512.png','./icon-192.svg','./icon-512.svg','./og-image.png','./style.css','./safety-hub.css','./video-affiliate.css','./catalog.css','./policy.css','./app.js','./safety-core.js','./scenario-manuals.js','./safety-hub.js','./guide-video.js','./affiliate.js','./share.js','./pwa.js'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE_NAME).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('safekit-shell-')&&key!==CACHE_NAME).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin)return;event.respondWith(fetch(request).then(response=>{if(response&&response.ok){const copy=response.clone();caches.open(CACHE_NAME).then(cache=>cache.put(request,copy))}return response}).catch(async()=>{const cached=await caches.match(request);if(cached)return cached;if(request.mode==='navigate')return caches.match('./index.html');return new Response('오프라인에서 사용할 수 있도록 먼저 사이트에 접속해 주세요.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}})}))});
